"""Build the Persian Hormuz presentation. Run with Python 3 and python-pptx.
Optional PDF preview: libreoffice --headless --convert-to pdf --outdir docs/presentation docs/presentation/Hormuz-15min-Draft-01.pptx
"""
from pathlib import Path
from pptx import Presentation
from pptx.util import Inches, Pt
from pptx.dml.color import RGBColor
from pptx.enum.shapes import MSO_SHAPE, MSO_CONNECTOR
from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
from pptx.oxml.xmlchemy import OxmlElement

OUT = Path(__file__).resolve().parent
prs = Presentation(); prs.slide_width = Inches(13.333); prs.slide_height = Inches(7.5)
NAVY='10283F'; BLUE='126D91'; TEAL='008D91'; GOLD='D98B24'; INK='183349'; MUTED='536C7C'; PALE='EEF5F8'; WHITE='FFFFFF'; RED='B94C42'; LINE='D8E4EA'
FONT='Vazirmatn'
agenda=[]
def rect(s,x,y,w,h,fill,line=None,radius=False):
 sh=s.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE if radius else MSO_SHAPE.RECTANGLE, Inches(x), Inches(y), Inches(w), Inches(h))
 sh.fill.solid(); sh.fill.fore_color.rgb=RGBColor.from_string(fill)
 sh.line.fill.background() if not line else None
 if line: sh.line.color.rgb=RGBColor.from_string(line)
 if radius:
  try: sh.adjustments[0]=0.12
  except Exception: pass
 return sh

def txt(s,text,x,y,w,h,size=22,color=INK,bold=False,align='right'):
 box=s.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h)); tf=box.text_frame
 tf.word_wrap=True; tf.margin_left=Inches(.04); tf.margin_right=Inches(.04); tf.margin_top=0; tf.margin_bottom=0
 for i,line in enumerate(text.split('\n')):
  p=tf.paragraphs[0] if i==0 else tf.add_paragraph(); p.alignment={'right':PP_ALIGN.RIGHT,'left':PP_ALIGN.LEFT,'center':PP_ALIGN.CENTER}[align]
  p.space_after=Pt(7); p.font.name=FONT; p.font.size=Pt(size)
  pp=p._p.get_or_add_pPr(); pp.set('rtl','1' if align!='left' else '0')
  r=p.add_run(); r.text=line; r.font.name=FONT; r.font.size=Pt(size); r.font.bold=bold; r.font.color.rgb=RGBColor.from_string(color)
  rp=r._r.get_or_add_rPr(); rp.set('lang','fa-IR')
  for tag in ['a:cs','a:ea']:
   el=OxmlElement(tag); el.set('typeface',FONT); rp.append(el)
 return box

def line(s,x1,y1,x2,y2,color=TEAL,width=2):
 sh=s.shapes.add_connector(MSO_CONNECTOR.STRAIGHT, Inches(x1), Inches(y1), Inches(x2), Inches(y2)); sh.line.color.rgb=RGBColor.from_string(color); sh.line.width=Pt(width); return sh

def arrow(s,x,y,w,h,color=TEAL,direction='right'):
 sh=s.shapes.add_shape(MSO_SHAPE.RIGHT_ARROW if direction=='right' else MSO_SHAPE.UP_ARROW, Inches(x), Inches(y), Inches(w), Inches(h)); sh.fill.solid(); sh.fill.fore_color.rgb=RGBColor.from_string(color); sh.line.fill.background(); return sh

def slide(title,kicker,seconds=None,source='D2 §۵–۱۰',dark=False):
 s=prs.slides.add_slide(prs.slide_layouts[6]); bg=NAVY if dark else 'FAFCFD'; s.background.fill.solid(); s.background.fill.fore_color.rgb=RGBColor.from_string(bg)
 rect(s,12.76,.42,.07,.48,GOLD)
 txt(s,kicker,.55,.36,11.95,.35,12,GOLD,True)
 txt(s,title,.55,.94,12.22,.88,30,WHITE if dark else NAVY,True)
 line(s,.6,6.93,12.72,6.93,'355068' if dark else LINE,1)
 n=len(prs.slides); txt(s,'هرمز  /  پیش‌نویس اول  /  '+('پیوست' if seconds is None else 'ارائه ۱۵ دقیقه‌ای'),6.3,7.08,6.4,.22,10,'AABFCC' if dark else MUTED)
 txt(s,f'{n:02d}   |   {source}',.6,7.06,5.6,.24,10,'AABFCC' if dark else MUTED,align='left')
 if seconds is not None: agenda.append((n,title,seconds))
 return s

def note(s,text,source):
 n=len(prs.slides); duration=next((v for i,t,v in agenda if i==n),None)
 s.notes_slide.notes_text_frame.text=(f'زمان پیشنهادی: {duration} ثانیه\n' if duration else 'پیوست؛ خارج از زمان اصلی ارائه\n')+text+'\n\nمنبع: '+source

def card(s,x,y,w,title,body,accent=TEAL,h=2.65):
 rect(s,x,y,w,h,WHITE,LINE,True); rect(s,x+w-.09,y+.22,.045,.5,accent)
 txt(s,title,x+.18,y+.24,w-.44,.58,22,accent,True)
 txt(s,body,x+.2,y+1.02,w-.4,h-1.1,19)

def rack(s,x,y,w=.68,h=1.65,active=True,sensors=False):
 rect(s,x+.07,y+.08,w,h,NAVY if active else 'B8C9D3',radius=True)
 rect(s,x,y,w,h,INK if active else 'D8E4EA',radius=True)
 for j in range(7):
  rect(s,x+.08,y+.15+j*(h-.3)/7,w-.16,.12,'36566D' if active else 'C0D0DB')
  if active: rect(s,x+.12,y+.18+j*(h-.3)/7,.04,.035,TEAL)
 if sensors:
  for a in [.2,.52,.82]:
   sh=s.shapes.add_shape(MSO_SHAPE.OVAL,Inches(x+w-.035),Inches(y+h*a),Inches(.1), Inches(.1)); sh.fill.solid();sh.fill.fore_color.rgb=RGBColor.from_string(GOLD);sh.line.fill.background()

